val Cream=Color(0xFFF4EFE7);val Ink=Color(0xFF2C211B);val Coffee=Color(0xFF5A4032)
data class Dish(val name:String,var price:Int,var cat:String,var enabled:Boolean=true,var imageUri:String?=null)
data class QrCfg(var bank:String="",var account:String="",var owner:String="",var prefix:String="0210",var enabled:Boolean=true,var printOnBill:Boolean=true)
fun money(v:Int)="%,dđ".format(v).replace(',','.')
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{Pos()}}}
@Composable fun Pos(){var screen by remember{mutableStateOf("TABLES")};var table by remember{mutableStateOf("Bàn 01")};val qr=remember{QrCfg()};val menu=remember{mutableStateListOf(Dish("Bún gà",40000,"Ăn sáng"),Dish("Bún gà đùi",55000,"Ăn sáng"),Dish("Cà phê đen",25000,"Cà phê"),Dish("Cà phê sữa",30000,"Cà phê"),Dish("Trà đào",35000,"Trà"),Dish("Sinh tố xoài",40000,"Sinh tố"))};val cart=remember{mutableStateMapOf<String,Int>()};fun home(){screen="TABLES"};BackHandler(screen!="TABLES"){screen=when(screen){"ORDER"->"TABLES";"SENT"->"ORDER";"PAY"->"SENT";"MENU_ADD"->"MENU";else->"TABLES"}};MaterialTheme(colorScheme=lightColorScheme(primary=Coffee,background=Cream,surface=Color(0xFFFFFCF7),onSurface=Ink)){Surface(Modifier.fillMaxSize(),color=Cream){Box(Modifier.fillMaxSize().windowInsetsPadding(WindowInsets.safeDrawing)){when(screen){"TABLES"->Tables({table=it;screen="ORDER"},{screen="MENU"},{screen="SETTINGS"});"ORDER"->Order(table,menu,cart,{screen="TABLES"},::home,{screen="SENT"});"SENT"->Sent(table,{screen="ORDER"},{screen="PAY"},::home);"PAY"->Pay(table,qr,{screen="SENT"},::home,{screen="SETTINGS"});"MENU"->MenuManager(menu,::home,{screen="MENU_ADD"});"MENU_ADD"->AddDish(menu){screen="MENU"};"SETTINGS"->QrSettings(qr,::home)}}}}}
@Composable fun Top(title:String,sub:String,onBack:(()->Unit)?=null,onHome:(()->Unit)?=null){Row(Modifier.fillMaxWidth().padding(horizontal=18.dp,vertical=12.dp),verticalAlignment=Alignment.CenterVertically){if(onBack!=null)TextButton(onBack){Text("‹ BACK",fontWeight=FontWeight.Bold)}else Text("0210",fontSize=27.sp,fontWeight=FontWeight.Black);Spacer(Modifier.weight(1f));Column(horizontalAlignment=Alignment.End){Text(title,fontWeight=FontWeight.Bold);Text(sub,fontSize=12.sp,color=Coffee)};if(onHome!=null)TextButton(onHome){Text("⌂",fontSize=24.sp)}}}
@Composable fun Tables(open:(String)->Unit,menu:()->Unit,settings:()->Unit){Column{Top("BÁN HÀNG","Chọn bàn");Row(Modifier.padding(horizontal=12.dp),verticalAlignment=Alignment.CenterVertically){TextButton(menu){Text("MENU")};TextButton(settings){Text("CÀI ĐẶT")};Spacer(Modifier.weight(1f));Text("TRONG NHÀ",fontWeight=FontWeight.Bold)};LazyColumn(Modifier.weight(1f).padding(horizontal=14.dp)){items((1..8).map{"Bàn %02d".format(it)}){x->Card(Modifier.fillMaxWidth().padding(5.dp).clickable{open(x)},shape=RoundedCornerShape(18.dp)){Row(Modifier.padding(20.dp)){Text(x,fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text("TRỐNG",fontSize=12.sp,color=Coffee)}}}};Button({open("Mang đi")},Modifier.fillMaxWidth().padding(18.dp).height(54.dp)){Text("MANG ĐI")}}}
@Composable fun Order(t:String,menu:List<Dish>,cart:MutableMap<String,Int>,back:()->Unit,home:()->Unit,send:()->Unit){var cat by remember{mutableStateOf("Tất cả")};val cats=listOf("Tất cả","Cà phê","Ăn sáng","Trà","Sinh tố");val count=cart.values.sum();val total=menu.sumOf{it.price*(cart[it.name]?:0)};Column{Top(t,"ORDER MÓN",back,home);Row(Modifier.fillMaxWidth().padding(horizontal=8.dp),horizontalArrangement=Arrangement.SpaceEvenly){cats.forEach{Text(it,Modifier.clickable{cat=it}.padding(6.dp),fontSize=13.sp,fontWeight=if(cat==it)FontWeight.Black else FontWeight.Normal)}};LazyColumn(Modifier.weight(1f).padding(12.dp)){items(menu.filter{it.enabled&&(cat=="Tất cả"||it.cat==cat)}){d->val q=cart[d.name]?:0;Card(Modifier.fillMaxWidth().padding(5.dp),shape=RoundedCornerShape(18.dp)){Row(Modifier.fillMaxWidth().padding(14.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(54.dp).background(Color(0xFFE5DDD7),RoundedCornerShape(12.dp)),contentAlignment=Alignment.Center){Text(if(d.imageUri==null)"ẢNH" else "✓",fontSize=11.sp)};Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text(d.name,fontWeight=FontWeight.Bold);Text(money(d.price),color=Coffee)};if(q>0){OutlinedButton({if(q<=1)cart.remove(d.name)else cart[d.name]=q-1},contentPadding=PaddingValues(0.dp),modifier=Modifier.size(40.dp)){Text("−")};Text("$q",Modifier.width(30.dp),fontWeight=FontWeight.Black);OutlinedButton({cart[d.name]=q+1},contentPadding=PaddingValues(0.dp),modifier=Modifier.size(40.dp)){Text("+")}}else Button({cart[d.name]=1}){Text("+")}}}}};Text("$count món • ${money(total)}",Modifier.padding(horizontal=18.dp),fontWeight=FontWeight.Black);Button(send,enabled=count>0,modifier=Modifier.fillMaxWidth().padding(18.dp).height(56.dp)){Text("GỬI LÀM HÀNG",fontWeight=FontWeight.Bold)}}}
@Composable fun Sent(t:String,more:()->Unit,pay:()->Unit,home:()->Unit){Column{Top(t,"ĐÃ GỌI",more,home);Card(Modifier.fillMaxWidth().padding(18.dp)){Column(Modifier.padding(20.dp)){Text("ĐƠN VỪA GỬI",fontWeight=FontWeight.Black);Text("Chờ in Bluetooth",color=Coffee)}};Spacer(Modifier.weight(1f));Row(Modifier.padding(18.dp)){OutlinedButton(more,Modifier.weight(1f)){Text("GỌI THÊM")};Spacer(Modifier.width(8.dp));Button(pay,Modifier.weight(1f)){Text("THANH TOÁN")}}}}
@Composable fun Pay(t:String,qr:QrCfg,back:()->Unit,done:()->Unit,setup:()->Unit){var method by remember{mutableStateOf("TRANSFER")};val configured=qr.bank.isNotBlank()&&qr.account.isNotBlank()&&qr.owner.isNotBlank();Column{Top(t,"THANH TOÁN",back,done);Column(Modifier.weight(1f).padding(22.dp)){Text("TỔNG CỘNG",color=Coffee);Text("135.000đ",fontSize=32.sp,fontWeight=FontWeight.Black);Spacer(Modifier.height(20.dp));Row{FilterChip(method=="CASH",{method="CASH"},{Text("TIỀN MẶT")});Spacer(Modifier.width(10.dp));FilterChip(method=="TRANSFER",{method="TRANSFER"},{Text("CHUYỂN KHOẢN")})};if(method=="TRANSFER")Card(Modifier.fillMaxWidth().padding(top=18.dp)){Column(Modifier.fillMaxWidth().padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){if(configured){Text("VIETQR ĐÃ CẤU HÌNH",fontWeight=FontWeight.Black);Text("${qr.bank} • ${qr.account}\n${qr.owner}\nNội dung: ${qr.prefix} ${t.replace("Bàn ","B")}",Modifier.padding(top=8.dp));Text("QR đồ họa sẽ được sinh ở bước tiếp theo.",Modifier.padding(top=8.dp),fontSize=12.sp,color=Coffee)}else{Text("CHƯA CẤU HÌNH VIETQR",fontWeight=FontWeight.Black);Button(setup,Modifier.padding(top=12.dp)){Text("CẤU HÌNH NGAY")}}}}};Button(done,Modifier.fillMaxWidth().padding(18.dp).height(58.dp)){Text(if(method=="CASH")"XÁC NHẬN ĐÃ TRẢ TIỀN MẶT" else "XÁC NHẬN ĐÃ NHẬN CHUYỂN KHOẢN",fontWeight=FontWeight.Bold)}}}
@Composable fun QrSettings(qr:QrCfg,back:()->Unit){var bank by remember{mutableStateOf(qr.bank)};var account by remember{mutableStateOf(qr.account)};var owner by remember{mutableStateOf(qr.owner)};var prefix by remember{mutableStateOf(qr.prefix)};var enabled by remember{mutableStateOf(qr.enabled)};var print by remember{mutableStateOf(qr.printOnBill)};Column{Top("CÀI ĐẶT","VietQR",back,back);LazyColumn(Modifier.weight(1f).padding(20.dp)){item{Text("THANH TOÁN VIETQR",fontWeight=FontWeight.Black,fontSize=20.sp);Text("Thông tin chỉ dùng để tạo QR thanh toán trên máy.",Modifier.padding(vertical=8.dp),color=Coffee);OutlinedTextField(bank,{bank=it},label={Text("Ngân hàng")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(10.dp));OutlinedTextField(account,{account=it.filter(Char::isDigit)},label={Text("Số tài khoản")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(10.dp));OutlinedTextField(owner,{owner=it.uppercase()},label={Text("Tên chủ tài khoản")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(10.dp));OutlinedTextField(prefix,{prefix=it.uppercase()},label={Text("Nội dung CK mặc định")},modifier=Modifier.fillMaxWidth());Row(verticalAlignment=Alignment.CenterVertically){Text("Hiển thị VietQR",Modifier.weight(1f));Switch(enabled,{enabled=it})};Row(verticalAlignment=Alignment.CenterVertically){Text("In QR trên bill",Modifier.weight(1f));Switch(print,{print=it})};Button({qr.bank=bank.trim();qr.account=account.trim();qr.owner=owner.trim();qr.prefix=prefix.trim().ifBlank{"0210"};qr.enabled=enabled;qr.printOnBill=print;back()},enabled=bank.isNotBlank()&&account.isNotBlank()&&owner.isNotBlank(),modifier=Modifier.fillMaxWidth().height(56.dp)){Text("LƯU CẤU HÌNH",fontWeight=FontWeight.Bold)}}}}}
@Composable fun MenuManager(menu:MutableList<Dish>,back:()->Unit,add:()->Unit){Column{Top("QUẢN LÝ MENU","V0.5",back,back);Button(add,Modifier.fillMaxWidth().padding(18.dp)){Text("+ THÊM MÓN")};LazyColumn(Modifier.weight(1f).padding(horizontal=14.dp)){items(menu){d->Card(Modifier.fillMaxWidth().padding(5.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(d.name,fontWeight=FontWeight.Bold);Text("${d.cat} • ${money(d.price)}")};Switch(d.enabled,{d.enabled=it;val i=menu.indexOf(d);menu[i]=d})}}}}}}
@Composable fun AddDish(menu:MutableList<Dish>,back:()->Unit){var name by remember{mutableStateOf("")};var price by remember{mutableStateOf("")};var cat by remember{mutableStateOf("Cà phê")};var image by remember{mutableStateOf<Uri?>(null)};var expanded by remember{mutableStateOf(false)};val picker=rememberLauncherForActivityResult(ActivityResultContracts.GetContent()){image=it};Column{Top("THÊM MÓN","Menu",back,back);Column(Modifier.padding(20.dp)){OutlinedTextField(name,{name=it},label={Text("Tên món")},modifier=Modifier.fillMaxWidth());OutlinedTextField(price,{price=it.filter(Char::isDigit)},label={Text("Giá bán")},modifier=Modifier.fillMaxWidth());Box{OutlinedButton({expanded=true},Modifier.fillMaxWidth()){Text("PHÂN LOẠI: $cat")};DropdownMenu(expanded,{expanded=false}){listOf("Cà phê","Ăn sáng","Trà","Sinh tố","Khác").forEach{x->DropdownMenuItem({Text(x)},{cat=x;expanded=false})}}};OutlinedButton({picker.launch("image/*")},Modifier.fillMaxWidth()){Text(if(image==null)"CHỌN ẢNH ĐẠI DIỆN" else "✓ ĐÃ CHỌN ẢNH")};Button({val p=price.toIntOrNull();if(name.isNotBlank()&&p!=null){menu.add(Dish(name,p,cat,true,image?.toString()));back()}},Modifier.fillMaxWidth().padding(top=18.dp)){Text("LƯU MÓN")}}}}